#include <Eigen/Dense>
#include <iostream>
#include <iomanip>
#include <cmath>

using namespace Eigen;

int main() {
    // Node coordinates
    // N1=(0,0,0), N2=(1,0,0), N3=(0,1,0), N4=(0,0,1)
    double x[4] = {0.0, 1.0, 0.0, 0.0};
    double y[4] = {0.0, 0.0, 1.0, 0.0};
    double z[4] = {0.0, 0.0, 0.0, 1.0};

    double E  = 200e9;
    double nu = 0.3;
    double GG = E / (2.0 * (1.0 + nu));

    // Build H matrix (4x4), row i = [1, xi, yi, zi]
    Matrix4d H;
    for (int i = 0; i < 4; ++i) {
        H(i, 0) = 1.0;
        H(i, 1) = x[i];
        H(i, 2) = y[i];
        H(i, 3) = z[i];
    }

    // Invert H and get determinant
    double HDETER = H.determinant();
    Matrix4d Hinv = H.inverse();

    // HDETER = abs
    HDETER = std::fabs(HDETER);

    // Build G material matrix (6x6)
    Matrix<double, 6, 6> G = Matrix<double, 6, 6>::Zero();
    double TEMP1 = (1.0 + nu) * (1.0 - 2.0 * nu);
    double g1 = E * (1.0 - nu) / TEMP1;
    double g2 = E * nu / TEMP1;

    // Fortran G is 1-indexed, stored column-major in a 6x6
    // G(1)=g1, G(8)=g1, G(15)=g1  -> diagonal (1,1),(2,2),(3,3)
    // G(2)=g2, G(3)=g2, G(7)=g2, G(9)=g2, G(13)=g2, G(14)=g2
    // G(22)=GG, G(29)=GG, G(36)=GG -> (4,4),(5,5),(6,6)
    // Fortran column-major: index k -> row = ((k-1)%6)+1, col = ((k-1)/6)+1
    G(0, 0) = g1;
    G(1, 1) = g1;
    G(2, 2) = g1;
    G(0, 1) = g2; G(1, 0) = g2;
    G(0, 2) = g2; G(2, 0) = g2;
    G(1, 2) = g2; G(2, 1) = g2;
    G(3, 3) = GG;
    G(4, 4) = GG;
    G(5, 5) = GG;

    // Build 4 C matrices (6x3 each). C is stored as 72 doubles, column-major.
    // For each I=1..4: J = 18*I - 18
    // C(J+1)=H(I+4), C(J+5)=H(I+8), C(J+9)=H(I+12),
    // C(J+11)=H(I+12), C(J+12)=H(I+8), C(J+13)=H(I+12),
    // C(J+15)=H(I+4), C(J+16)=H(I+8), C(J+17)=H(I+4)
    //
    // H is 4x4 column-major: H(k) -> row=((k-1)%4)+1, col=((k-1)/4)+1
    // H(I+4): k=I+4 -> row=((I+3)%4)+1, col=((I+3)/4)+1
    //   For I=1: k=5 -> row=1,col=2 ; I=2: k=6 -> row=2,col=2
    //   I=3: k=7 -> row=3,col=2 ; I=4: k=8 -> row=4,col=2
    //   So H(I+4) = H(row=I, col=2) = y[I-1]  (since H col2 = y)
    // H(I+8): k=I+8 -> row=((I+7)%4)+1, col=((I+7)/4)+1
    //   I=1: k=9 -> row=1,col=3 ; ... So H(I+8) = H(row=I, col=3) = z[I-1]
    // H(I+12): k=I+12 -> row=((I+11)%4)+1, col=((I+11)/4)+1
    //   I=1: k=13 -> row=1,col=4 ; So H(I+12) = H(row=I, col=4) = 1.0

    // C matrix for element I is 6x3, stored column-major in C(J+1..J+18)
    // C(J+1) -> (row1,col1), C(J+5) -> (row5,col1), C(J+9) -> (row3,col2)
    // Let's map: within block, index m=1..18, row=((m-1)%6)+1, col=((m-1)/6)+1
    // C(J+1): m=1 -> (1,1)
    // C(J+5): m=5 -> (5,1)
    // C(J+9): m=9 -> (3,2)
    // C(J+11): m=11 -> (5,2)
    // C(J+12): m=12 -> (6,2)
    // C(J+13): m=13 -> (1,3)
    // C(J+15): m=15 -> (3,3)
    // C(J+16): m=16 -> (4,3)
    // C(J+17): m=17 -> (5,3)

    // So for element I:
    //   H(I+4)  = y[I-1]  -> C(1,1), C(3,3), C(5,3)
    //   H(I+8)  = z[I-1]  -> C(5,1), C(6,2), C(4,3)
    //   H(I+12) = 1.0     -> C(3,2), C(5,2), C(1,3)

    // Wait, let me recheck. C(J+1)=H(I+4) -> (1,1)
    // C(J+5)=H(I+8) -> (5,1)
    // C(J+9)=H(I+12) -> (3,2)
    // C(J+11)=H(I+12) -> (5,2)
    // C(J+12)=H(I+8) -> (6,2)
    // C(J+13)=H(I+12) -> (1,3)
    // C(J+15)=H(I+4) -> (3,3)
    // C(J+16)=H(I+8) -> (4,3)
    // C(J+17)=H(I+4) -> (5,3)

    // So:
    //   H(I+4)  = y[I-1]  appears at (1,1), (3,3), (5,3)
    //   H(I+8)  = z[I-1]  appears at (5,1), (6,2), (4,3)
    //   H(I+12) = 1.0     appears at (3,2), (5,2), (1,3)

    // Build C matrices
    Matrix<double, 6, 3> Cmat[4];
    for (int I = 0; I < 4; ++I) {
        Cmat[I] = Matrix<double, 6, 3>::Zero();
        double hI4  = y[I];   // H(I+4)
        double hI8  = z[I];   // H(I+8)
        double hI12 = 1.0;    // H(I+12)

        Cmat[I](0, 0) = hI4;   // (1,1)
